```json
{
  "root_causes": [
    {
      "service": "ts-train-food-service",
      "fault_kind": "network_partition",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'norm' src, service_name, count(*) n, min(\"time\") t0, max(\"time\") t1 FROM normal_traces WHERE service_name='ts-train-food-service' GROUP BY 1,2 UNION ALL SELECT 'ab', service_name, count(*), min(\"time\"), max(\"time\") FROM abnormal_traces WHERE service_name='ts-train-food-service' GROUP BY 1,2",
          "claim": "ts-train-food-service served 635 spans before the incident but only 5, all at 04:14:02, during the abnormal window."
        },
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name pod, metric, count(*) n, min(\"time\") t0, max(\"time\") t1 FROM abnormal_metrics WHERE service_name='ts-train-food-service' AND metric='container.memory.usage' GROUP BY 1,2",
          "claim": "The same train-food pod kept emitting container metrics through the abnormal window, so the pod was alive and reachable in principle."
        },
        {
          "kind": "log",
          "sql": "SELECT count(*) n FROM abnormal_logs l WHERE service_name='ts-food-service' AND level='SEVERE' AND contains(cast(to_json(l) as varchar), 'ts-train-food-service')",
          "claim": "ts-food-service SEVERE logs show I/O errors calling ts-train-food-service with 'Connection timed out'."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'norm' src, sum(value) syn_flags FROM normal_metrics_sum WHERE metric='hubble_tcp_flags_total' AND attr_source LIKE '%ts-food-service%' AND attr_destination LIKE '%ts-train-food-service%' UNION ALL SELECT 'ab', sum(value) FROM abnormal_metrics_sum WHERE metric='hubble_tcp_flags_total' AND attr_source LIKE '%ts-food-service%' AND attr_destination LIKE '%ts-train-food-service%'",
          "claim": "TCP flag counts on the food-to-train-food connection rose from 3019 to 4204 while the connection's successful requests vanished, consistent with unanswered SYN retries."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-train-food-service",
      "to": "ts-food-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind, attr_status_code, count(*) n, approx_quantile(duration,0.5)/1e6 med_ms, max(duration)/1e6 max_ms FROM abnormal_traces WHERE service_name='ts-food-service' AND attr_span_kind='Client' GROUP BY 1,2,3",
          "claim": "Food-service's outbound client calls hang for about 130 s and end in error, or stall for tens of seconds, instead of returning quickly."
        }
      ]
    },
    {
      "from": "ts-food-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT s.service_name, s.attr_span_kind, s.attr_status_code, count(*) n, approx_quantile(s.duration,0.5)/1e6 med_ms, max(s.duration)/1e6 max_ms FROM abnormal_traces s WHERE (s.service_name='ts-food-service' AND s.attr_span_kind='Server') OR (s.service_name='ts-ui-dashboard' AND s.span_name LIKE '%foods%') GROUP BY 1,2,3",
          "claim": "Food-service server spans fail after about 130 s, and the dashboard's food requests take about 20 s, which is what users see."
        }
      ]
    }
  ]
}
```

